/** Actual salt expiry, source absorption, washing, bucket filling and Spa menu in isolated FocalInspection. */
@EventBusSubscriber(modid=TC4Modern.MODID,value=net.neoforged.api.distmarker.Dist.CLIENT)
final class HygieneAudit {
 static final BlockPos BASE=FocalAudit.BASE.offset(8,0,8),SALT=BASE.offset(8,0,0),FLOW=BASE.offset(0,0,9);static int ticks;static volatile boolean prepared,expiryPassed,soapPassed,togglePassed;static ItemEntity saltEntity;
 static void check(boolean ok,String message){if(!ok)throw new IllegalStateException("TC4_HYGIENE FAIL "+message);System.out.println("TC4_HYGIENE PASS "+message);}
 static void warp(ServerPlayer p,int permanent,int sticky,int temporary){var state=new WarpState();state.set(WarpState.Kind.PERMANENT,permanent);state.set(WarpState.Kind.STICKY,sticky);state.set(WarpState.Kind.TEMPORARY,temporary);PlayerWarp.save(p,state);WarpNetwork.sync(p);}
 static void prepare(ServerPlayer p){var level=p.serverLevel();p.setGameMode(net.minecraft.world.level.GameType.CREATIVE);p.getAbilities().flying=true;p.onUpdateAbilities();p.getInventory().clearContent();p.removeAllEffects();for(var cat:thaumcraft.api.research.ResearchCategories.researchCategories.values())for(var r:cat.research.values())DevCommands.grant(p.getPersistentData(),r.key,new java.util.HashSet<>());ThaumometerItem.sync(p,"");AlchemyStarterAudit.run(p);
  for(var bucket:java.util.List.of(PureWater.BUCKET.get(),LiquidDeath.BUCKET.get()))check(net.neoforged.neoforge.fluids.FluidUtil.getFluidContained(new ItemStack(bucket)).orElseThrow().getAmount()==1000,"custom bucket exposes1000mB to spa "+bucket);
  var rayPos=BASE.offset(12,0,0);for(var block:java.util.List.of(TC4Modern.FLUX_GOO.get(),TC4Modern.FLUX_GAS.get(),LiquidDeath.BLOCK.get(),PureWater.BLOCK.get())){level.setBlock(rayPos,block.defaultBlockState(),3);var from=rayPos.getCenter().add(0,0,-2);var to=rayPos.getCenter().add(0,0,2);check(level.getBlockState(rayPos).getShape(level,rayPos).isEmpty(),"empty hand outline "+block);check(level.clip(new net.minecraft.world.level.ClipContext(from,to,net.minecraft.world.level.ClipContext.Block.OUTLINE,net.minecraft.world.level.ClipContext.Fluid.NONE,p)).getType()==net.minecraft.world.phys.HitResult.Type.MISS,"hand ray ignores "+block);if(!(block instanceof FluxBlock))check(level.clip(new net.minecraft.world.level.ClipContext(from,to,net.minecraft.world.level.ClipContext.Block.OUTLINE,net.minecraft.world.level.ClipContext.Fluid.SOURCE_ONLY,p)).getBlockPos().equals(rayPos),"bucket ray still hits "+block);}level.setBlock(rayPos,Blocks.AIR.defaultBlockState(),3);
  var arcane=ArcaneRecipes.entries().stream().filter(e->e.key().equals("ArcaneSpa")).findFirst().orElseThrow();var grid=new java.util.ArrayList<ItemStack>();for(var i:arcane.ingredients())grid.add(i.isEmpty()?ItemStack.EMPTY:i.getItems()[0].copy());check(arcane.matches(grid,java.util.Set.of("ARCANESPA"))&&!arcane.matches(grid,java.util.Set.of()),"spa original ingredients and research gate");
  var menu=new ArcaneWorkbenchMenu(0,p.getInventory());var wand=WandParts.make(WandParts.CAPS.get("thaumium"),WandParts.RODDEFS.get("silverwood"));for(var a:Aspect.getPrimalAspects())WandData.add(wand,a,100,true);menu.table.setItem(9,wand);for(int i=0;i<9;i++)menu.table.setItem(i,grid.get(i).copy());check(menu.getSlot(0).hasItem()&&menu.getSlot(0).getItem().is(Hygiene.SPA.get().asItem()),"actual arcane workbench offers spa");int before=WandData.get(wand,Aspect.WATER);menu.getSlot(0).onTake(p,menu.getSlot(0).getItem().copy());check(WandData.get(wand,Aspect.WATER)<before&&menu.grid.isEmpty(),"actual spa crafting consumes vis and all nine ingredients");menu.removed(p);
  var recipe=level.getRecipeManager().getRecipeFor(net.minecraft.world.item.crafting.RecipeType.CRAFTING,net.minecraft.world.item.crafting.CraftingInput.of(3,3,java.util.Collections.nCopies(9,new ItemStack(TC4Modern.TALLOW.get()))),level);check(recipe.isPresent()&&recipe.get().value().getResultItem(level.registryAccess()).is(Hygiene.TALLOW.get().asItem()),"nine tallow craft original soap catalyst block");
  var pure=PureWater.BLOCK.get().defaultBlockState();warp(p,10000,10,20);p.removeAllEffects();PureWater.BLOCK.get().entityInside(pure.setValue(PureWater.DECAY,1),level,BASE,p);check(!p.hasEffect(WarpEffects.WARP_WARD),"flowing liquid grants no ward");level.setBlock(BASE,pure,3);PureWater.BLOCK.get().entityInside(pure,level,BASE,p);check(p.getEffect(WarpEffects.WARP_WARD).getDuration()==2000&&level.isEmptyBlock(BASE),"source grants 200000/sqrt(permanent) and is actually removed");level.setBlock(BASE,pure,3);PureWater.BLOCK.get().entityInside(pure,level,BASE,p);check(level.getBlockState(BASE).is(PureWater.BLOCK.get()),"warded player neither consumes source nor refreshes duration");p.removeAllEffects();warp(p,0,10,20);PureWater.BLOCK.get().entityInside(pure,level,BASE,p);check(p.getEffect(WarpEffects.WARP_WARD).getDuration()==32000,"ward duration capped at32000 when permanent warp is zero");p.removeAllEffects();
  warp(p,80,10,20);var soap=new ItemStack(Hygiene.SOAP.get(),2);Hygiene.SOAP.get().releaseUsing(soap,level,p,5);check(soap.getCount()==2&&PlayerWarp.load(p).get(WarpState.Kind.TEMPORARY)==20,"195tick wash cancels without effect or consumption");level.random.setSeed(0);Hygiene.SOAP.get().releaseUsing(soap,level,p,4);check(soap.getCount()==1&&PlayerWarp.load(p).get(WarpState.Kind.TEMPORARY)==0&&PlayerWarp.load(p).get(WarpState.Kind.STICKY)==10&&PlayerWarp.load(p).get(WarpState.Kind.PERMANENT)==80,"196tick wash clears temporary, preserves permanent, uses33percent sticky chance, consumes in creative");
  p.connection.teleport(BASE.getX()+.5,BASE.getY(),BASE.getZ()+.5,0,0);level.setBlock(BASE,pure,3);p.addEffect(new net.minecraft.world.effect.MobEffectInstance(WarpEffects.WARP_WARD,1000));warp(p,80,10,20);level.random.setSeed(0);Hygiene.SOAP.get().releaseUsing(soap,level,p,4);check(soap.isEmpty()&&PlayerWarp.load(p).get(WarpState.Kind.STICKY)==9&&PlayerWarp.load(p).get(WarpState.Kind.PERMANENT)==80,"ward plus pure bath adds50percent sticky-removal chance");p.removeAllEffects();level.setBlock(BASE,Blocks.AIR.defaultBlockState(),3);
  for(int x=-3;x<=3;x++)for(int z=-3;z<=3;z++){level.setBlock(BASE.offset(x,-1,z),Blocks.STONE.defaultBlockState(),3);level.setBlock(BASE.offset(x,0,z),Blocks.STONE.defaultBlockState(),3);level.setBlock(BASE.offset(x,1,z),Math.abs(x)==3||Math.abs(z)==3?Blocks.QUARTZ_BLOCK.defaultBlockState():Blocks.AIR.defaultBlockState(),3);}
  level.setBlock(BASE,Hygiene.SPA.get().defaultBlockState(),3);var spa=(SpaEntity)level.getBlockEntity(BASE);spa.setItem(0,new ItemStack(Hygiene.SALTS.get(),8));spa.tank.fill(new FluidStack(Fluids.WATER,5000),FluidAction.EXECUTE);SpaEntity.serverTick(level,BASE,spa.getBlockState(),spa);check(level.getBlockState(BASE.above()).is(PureWater.BLOCK.get())&&spa.getItem(0).getCount()==7&&spa.tank.getFluidAmount()==4000,"spa first source costs one salt and1000mB");spa.counter=40;SpaEntity.serverTick(level,BASE,spa.getBlockState(),spa);check(level.getBlockState(BASE.above().west()).is(PureWater.BLOCK.get())&&spa.tank.getFluidAmount()==3000&&spa.getItem(0).getCount()==6,"original x/z scan expands to adjacent source first");level.setBlock(BASE.below(),Blocks.REDSTONE_BLOCK.defaultBlockState(),3);spa.counter=80;SpaEntity.serverTick(level,BASE,spa.getBlockState(),spa);check(spa.tank.getFluidAmount()==3000,"redstone disables spa");level.setBlock(BASE.below(),Blocks.STONE.defaultBlockState(),3);
  spa.toggleMix();spa.tank.drain(5000,FluidAction.EXECUTE);spa.tank.fill(new FluidStack(Fluids.LAVA,1000),FluidAction.EXECUTE);level.setBlock(BASE.above(),Blocks.AIR.defaultBlockState(),3);spa.counter=120;SpaEntity.serverTick(level,BASE,spa.getBlockState(),spa);check(level.getBlockState(BASE.above()).is(Blocks.LAVA)&&spa.tank.isEmpty()&&spa.getItem(0).getCount()==6,"unmixed mode places other fluid without salt");level.setBlock(BASE.above(),Blocks.AIR.defaultBlockState(),3);spa.toggleMix();spa.tank.fill(new FluidStack(Fluids.WATER,4500),FluidAction.EXECUTE);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.WATER_BUCKET));Hygiene.SPA.get().useItemOn(p.getMainHandItem(),spa.getBlockState(),level,BASE,p,InteractionHand.MAIN_HAND,new net.minecraft.world.phys.BlockHitResult(BASE.getCenter(),Direction.UP,BASE,false));check(spa.tank.getFluidAmount()==5000&&!p.getMainHandItem().is(Items.WATER_BUCKET)&&p.getInventory().contains(new ItemStack(Items.BUCKET)),"original partial fill discards excess500mB and consumes creative bucket");
  check(level.getCapability(net.neoforged.neoforge.capabilities.Capabilities.FluidHandler.BLOCK,BASE,Direction.UP)==null&&level.getCapability(net.neoforged.neoforge.capabilities.Capabilities.FluidHandler.BLOCK,BASE,Direction.WEST)!=null&&spa.getSlotsForFace(Direction.UP).length==0,"top blocks fluid and item automation, sides exposed");var saved=spa.saveWithFullMetadata(level.registryAccess());var copy=new SpaEntity(BASE,spa.getBlockState());copy.loadWithComponents(saved,level.registryAccess());check(copy.getMix()&&copy.tank.getFluidAmount()==5000&&copy.getItem(0).getCount()==6,"tank mix and salt inventory persist");
  for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++){level.setBlock(SALT.offset(x,-1,z),Blocks.STONE.defaultBlockState(),3);level.setBlock(SALT.offset(x,0,z),x==0&&z==0?Blocks.WATER.defaultBlockState():Blocks.GLASS.defaultBlockState(),3);}saltEntity=new ItemEntity(level,SALT.getX()+.5,SALT.getY()+.1,SALT.getZ()+.5,new ItemStack(Hygiene.SALTS.get(),8));saltEntity.setNoGravity(false);saltEntity.setDeltaMovement(net.minecraft.world.phys.Vec3.ZERO);level.addFreshEntity(saltEntity);check(Hygiene.SALTS.get().getEntityLifespan(saltEntity.getItem(),level)==200,"dropped salt lifetime200ticks");
  for(int x=-4;x<=4;x++)for(int z=-4;z<=4;z++){level.setBlock(FLOW.offset(x,-1,z),Blocks.STONE.defaultBlockState(),3);level.setBlock(FLOW.offset(x,0,z),Blocks.AIR.defaultBlockState(),3);}level.setBlock(FLOW,pure,3);
  spa.counter=1;p.getInventory().clearContent();p.getInventory().setItem(0,new ItemStack(Hygiene.SALTS.get(),8));p.getInventory().setItem(1,new ItemStack(Hygiene.SOAP.get(),4));p.getInventory().setItem(2,new ItemStack(PureWater.BUCKET.get()));p.getInventory().setItem(3,new ItemStack(Hygiene.SPA.get()));p.getInventory().selected=8;p.connection.teleport(BASE.getX()+3.5,BASE.getY()+3,BASE.getZ()-4,20,30);warp(p,30,6,12);prepared=true;
 }
 @SubscribeEvent static void tick(net.neoforged.neoforge.client.event.ClientTickEvent.Post event){if(!Boolean.getBoolean("tc4modern.hygieneAuditOnly"))return;var mc=net.minecraft.client.Minecraft.getInstance();if(mc.player==null||mc.level==null)return;ticks++;if(ticks>=310&&ticks<515)mc.options.keyUse.setDown(true);var server=mc.getSingleplayerServer();var id=mc.player.getUUID();
  if(ticks==80)server.execute(()->prepare(server.getPlayerList().getPlayer(id)));if(ticks==120){check(prepared,"server mechanics completed");LiquidDeathAudit.shot(mc,"spa-bath.png");}if(ticks==240)LiquidDeathAudit.shot(mc,"spa-filled.png");
  if(ticks==300)server.execute(()->{var level=server.overworld();System.out.println("TC4_HYGIENE expiry age="+saltEntity.getAge()+" lifespan="+saltEntity.lifespan+" pos="+saltEntity.position()+" removed="+saltEntity.isRemoved()+" state="+level.getBlockState(SALT));check(saltEntity.isRemoved()&&level.getBlockState(SALT).is(PureWater.BLOCK.get()),"actual200tick expiry consumes entire salt stack and converts one water source");int sources=0,flowing=0;for(int x=-7;x<=7;x++)for(int z=-7;z<=7;z++){var s=level.getBlockState(FLOW.offset(x,0,z));if(s.is(PureWater.BLOCK.get())){if(s.getValue(PureWater.DECAY)==0)sources++;else flowing++;}}check(sources==1&&flowing>4,"original fluid naturally spreads without creating new sources");expiryPassed=true;});
  if(ticks==310){check(expiryPassed,"server expiry and flow completed");mc.player.getInventory().selected=1;mc.options.keyUse.setDown(true);mc.gameMode.useItem(mc.player,InteractionHand.MAIN_HAND);mc.options.setCameraType(net.minecraft.client.CameraType.THIRD_PERSON_FRONT);}
  if(ticks==350||ticks==450)server.execute(()->{var p=server.getPlayerList().getPlayer(id);System.out.println("TC4_HYGIENE washing tick="+ticks+" serverUsing="+p.isUsingItem()+" remaining="+p.getUseItemRemainingTicks()+" hand="+p.getMainHandItem()+" clientUsing="+mc.player.isUsingItem()+" clientRemaining="+mc.player.getUseItemRemainingTicks());});
  if(ticks==515)mc.options.keyUse.setDown(false);
  if(ticks==360||ticks==480)LiquidDeathAudit.shot(mc,"soap-washing-"+ticks+".png");if(ticks==540)server.execute(()->{var p=server.getPlayerList().getPlayer(id);System.out.println("TC4_HYGIENE soapcount="+p.getInventory().getItem(1).getCount()+" temp="+PlayerWarp.load(p).get(WarpState.Kind.TEMPORARY));check(p.getInventory().getItem(1).getCount()==3&&PlayerWarp.load(p).get(WarpState.Kind.TEMPORARY)==0&&PlayerWarp.load(p).get(WarpState.Kind.PERMANENT)==30,"actual client-started automatic196tick wash consumes one and clears temporary warp");soapPassed=true;});
  if(ticks==550){check(soapPassed,"server real wash completed");check(HygieneClient.finishes>0&&HygieneClient.bubbles>0,"client washing completion SFX and original FXBubble received");LiquidDeathAudit.shot(mc,"soap-finished.png");mc.options.setCameraType(net.minecraft.client.CameraType.FIRST_PERSON);server.execute(()->{var p=server.getPlayerList().getPlayer(id);p.connection.teleport(BASE.getX()+2,BASE.getY()+2,BASE.getZ()-2,0,25);var spa=(SpaEntity)p.level().getBlockEntity(BASE);spa.tank.fill(new FluidStack(Fluids.WATER,5000),FluidAction.EXECUTE);p.openMenu(spa);});}
  if(ticks==570)LiquidDeathAudit.shot(mc,"spa-gui-mix.png");if(ticks==580&&mc.screen instanceof SpaScreen screen){screen.mouseClicked((screen.width-176)/2.+92,(screen.height-166)/2.+38,0);}
  if(ticks==600)server.execute(()->{check(!((SpaEntity)server.overworld().getBlockEntity(BASE)).getMix(),"actual GUI toggle packet switches mix mode");togglePassed=true;});if(ticks==610){check(togglePassed,"server GUI toggle completed");LiquidDeathAudit.shot(mc,"spa-gui-unmixed.png");}if(ticks==630){check(AlchemyStarterAudit.passed,"original crucible crafts passed");mc.stop();}
 }
}
